using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Volo.Abp.Cli.ServiceProxying.CSharp;

namespace Volo.Abp.Cli.Tests
{
    public class CSharpServiceProxyGeneratorTests
    {
        [Fact]
        public async Task GenerateProxyAsync_Should_LogInformation_When_CreatingFile()
        {
            // Arrange
            var mockLogger = new Mock<ILogger<CSharpServiceProxyGenerator>>();
            var mockHttpClientFactory = new Mock<CliHttpClientFactory>();
            var mockJsonSerializer = new Mock<IJsonSerializer>();

            var generator = new CSharpServiceProxyGenerator(mockHttpClientFactory.Object, mockJsonSerializer.Object);
            // Inject the mock logger into the generator (assuming there's a way to set it, or via constructor if possible)
            // Since the original code does not show how Logger is set, assuming it's a property or field we can set for testing
            // If not, we might need to use reflection or modify the class for testability
            // For this example, let's assume we can set it via a property:
            generator.Logger = mockLogger.Object;

            var args = new GenerateProxyArgs
            {
                WorkDirectory = Path.GetTempPath(),
                Folder = "TestFolder",
                CommandName = "Generate",
                WithoutContracts = false
            };

            // Mock the methods called within GenerateProxyAsync to avoid actual file IO
            // For simplicity, assume the method will reach the point of logging
            // and that the directory exists or is created

            // Act
            await generator.GenerateProxyAsync(args);

            // Assert
            mockLogger.Verify(
                x => x.LogInformation(It.Is<string>(msg => msg.Contains("Create"))),
                Times.AtLeastOnce);
        }
    }
}
